<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\UserProfile\Domain\ValueObject\Accessor\UserProfilePreferredUsernameAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the UserProfilePreferredUsernameAccessor trait.
 *
 * Covers null default, string/VO assignment via withPreferredUsername,
 * getPreferredUsername/preferredUsername accessors, and isPreferredUsernameChanged with/without original.
 */
class UserProfilePreferredUsernameAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withPreferredUsername creates a new instance with the PreferredUsername set
     * from a string value, and getPreferredUsername returns the primitive string.
     */
    public function testWithPreferredUsernameFromString(): void
    {
        // Arrange
        $holder = new ImplWithUserProfilePreferredUsernameAccessorUnitTest();

        // Act
        $result = $holder->withPreferredUsername('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->getPreferredUsername());
    }
    /**
     * Asserts that withpreferredUsername has access to the value object
     * from a string value, and getPreferredUsername returns the primitive string.
     */
    public function testWithPreferredUsernameFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithUserProfilePreferredUsernameAccessorUnitTest();

        // Act
        $result = $holder->withPreferredUsername('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->preferredUsername()->value());
    }
    public function testChangedPreferredUsername(): void
    {
        // Arrange
        $holder = new ImplWithUserProfilePreferredUsernameAccessorUnitTest();
        $original = $holder->withPreferredUsername('one');
        $same = $holder->withPreferredUsername('one');
        $modified = $holder->withPreferredUsername('other');

        // Act
        $unchanged = $holder->isPreferredUsernameChanged();
        $withSame = $original->isPreferredUsernameChanged($same);
        $withDiferent = $original->isPreferredUsernameChanged($modified);

        // Assert
        $this->assertFalse($unchanged);
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithUserProfilePreferredUsernameAccessorUnitTest
{
    use UserProfilePreferredUsernameAccessor;
}
